#!/usr/bin/env node
"use strict";

/**
 * Build-time copy of packages/core runtime contract assets into apps/web/public/.
 * apps/web/public/{data,i18n,fonts}/ are build artifacts (see apps/web/.gitignore)
 * regenerated by this script on every build. Run before build-i18n-html.js.
 */

const fs = require("fs");
const path = require("path");

const WEB_ROOT = path.resolve(__dirname, "..");
const REPO_ROOT = path.resolve(__dirname, "..", "..", "..");
const CORE_DIR = path.join(REPO_ROOT, "packages", "core");
const PUBLIC_DIR = path.join(WEB_ROOT, "public");

function copyFile(src, dest) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
  console.log("Copied", path.relative(REPO_ROOT, src), "->", path.relative(REPO_ROOT, dest));
}

function copyJsonFilesInDir(srcDir, destDir) {
  if (!fs.existsSync(srcDir)) return;
  for (const entry of fs.readdirSync(srcDir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      copyJsonFilesInDir(path.join(srcDir, entry.name), path.join(destDir, entry.name));
    } else if (entry.isFile() && entry.name.endsWith(".json")) {
      copyFile(path.join(srcDir, entry.name), path.join(destDir, entry.name));
    }
  }
}

function main() {
  // packages/core/data/*.json -> apps/web/public/data/*.json
  copyJsonFilesInDir(path.join(CORE_DIR, "data"), path.join(PUBLIC_DIR, "data"));

  // packages/core/i18n/*.json + packages/core/i18n/phonemes/*.json -> apps/web/public/i18n/**
  copyJsonFilesInDir(path.join(CORE_DIR, "i18n"), path.join(PUBLIC_DIR, "i18n"));

  // packages/core/fonts/*.woff2 -> apps/web/public/fonts/*.woff2
  const fontsDir = path.join(CORE_DIR, "fonts");
  if (fs.existsSync(fontsDir)) {
    for (const entry of fs.readdirSync(fontsDir, { withFileTypes: true })) {
      if (entry.isFile() && entry.name.endsWith(".woff2")) {
        copyFile(path.join(fontsDir, entry.name), path.join(PUBLIC_DIR, "fonts", entry.name));
      }
    }
  }
}

main();
